param([string]$Workspace='C:/Users/dnath/Documents/Heroes Dawn')
$ErrorActionPreference='Stop'
$root=Join-Path $Workspace 'Code/Heroes Dawn Unity/Assets/_Project/Art/UI/AubeTactiqueKit'
$manifest=Get-Content (Join-Path $root 'manifest.json') -Raw | ConvertFrom-Json
$records=@();foreach($item in $manifest.items) {
    $image=if($item.kind -eq 'portrait-sprite'){$item.preview}elseif($item.kind -eq 'font-or-license'){''}else{$item.file}
    $preview=if($image){[IO.Path]::GetRelativePath($root,(Join-Path $Workspace $image)).Replace('\','/')}else{''}
    $file=[IO.Path]::GetRelativePath($root,(Join-Path $Workspace $item.file)).Replace('\','/')
    $source=if($item.source){[IO.Path]::GetRelativePath($root,(Join-Path $Workspace $item.source)).Replace('\','/')}else{''}
    $records+=[ordered]@{id=$item.id;category=$item.category;file=$file;source=$source;preview=$preview;kind=$item.kind;width=$item.width;height=$item.height;border=$item.border;usage=$item.usage}
}
$reference=[IO.Path]::GetRelativePath($root,(Join-Path $Workspace '03_Art_UI_UX/Aube_Tactique_2026-11-04/index.html')).Replace('\','/')
$recordJson=$records | ConvertTo-Json -Depth 7 -Compress
$head=@'
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Heroes Dawn — Kit Aube tactique</title>
<style>
@font-face{font-family:Barlow;src:url('Fonts/Barlow-Regular.ttf')}@font-face{font-family:DawnTitle;src:url('Fonts/BarlowCondensed-ExtraBoldItalic.ttf')}
*{box-sizing:border-box}body{margin:0;background:#101c29;color:#ece7dc;font:17px/1.5 Barlow,system-ui}header,main,footer{max-width:1600px;margin:auto;padding:30px}header{border-bottom:1px solid #d6af5b}h1,h2,h3{font-family:DawnTitle,system-ui;font-weight:normal}h1{font-size:52px;margin:12px 0}p{max-width:1050px;color:#bbc7cc}a{color:#d6af5b}button,input{font:inherit}input{background:#142331;color:#ece7dc;border:1px solid #78858b;padding:12px;width:min(100%,480px)}button{background:#1c2d3b;color:#ece7dc;border:1px solid #78858b;padding:10px 16px;cursor:pointer}button.active{background:#ece7dc;color:#101c29;border-color:#d6af5b}.toolbar{position:sticky;top:0;background:#101c29f5;border-bottom:1px solid #78858b;z-index:3;padding:14px 30px}.toolbar>div{max-width:1540px;margin:auto;display:flex;gap:12px;flex-wrap:wrap}.groups{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px}.card{background:#1a2a37;border:1px solid #526571;min-width:0}.preview{height:210px;display:flex;align-items:center;justify-content:center;padding:18px;background:#142331}.preview img{max-width:100%;max-height:100%;object-fit:contain}.checker .preview{background:repeating-conic-gradient(#34414c 0% 25%,#1c2d3b 0% 50%) 50%/24px 24px}.meta{padding:16px}.meta h3{overflow-wrap:anywhere;font-size:23px;margin:0 0 10px}.meta p{font-size:14px;margin:4px 0}.links{display:flex;gap:16px;margin-top:14px}.dim{font-size:13px;color:#a1b0b8}.small{font-size:14px}.fontpreview{font-family:DawnTitle;font-size:34px}.demo{position:relative;aspect-ratio:20/9;min-height:340px;overflow:hidden;border:1px solid #d6af5b;background:#101c29 url('Illustrations/Production/hq-new-york.png') center/cover;margin:24px 0 36px}.demo:before{content:'';position:absolute;inset:0;background:#101c2966}.demohead{position:absolute;top:0;left:0;right:0;height:14%;background:#101c29ed;display:flex;align-items:center;justify-content:space-between;padding:0 3%;font-family:DawnTitle;font-size:clamp(20px,2.4vw,38px)}.demorail{position:absolute;top:19%;left:3%;width:17%;display:grid;gap:12px}.demotab{padding:12px;background:#101c29ed;border:1px solid #78858b;font-family:DawnTitle}.demotab.selected{background:#ece7dc;color:#101c29;border-color:#d6af5b}.demooffers{position:absolute;top:19%;bottom:17%;left:22%;width:40%;display:flex;gap:3%}.offer{position:relative;width:48.5%;overflow:hidden;border:1px solid #d6af5b;background:#101c29}.offer img{width:100%;height:100%;object-fit:cover}.offer span{position:absolute;bottom:0;left:0;right:0;padding:14px;background:#101c29e8;font-family:DawnTitle;font-size:clamp(18px,1.9vw,30px)}.demodetail{position:absolute;top:19%;bottom:17%;right:3%;width:32%;padding:2%;background:#101c29f5;border:1px solid #d6af5b}.demodetail h3{font-size:clamp(24px,2.5vw,38px);margin:0 0 15px}.demodetail p{font-size:clamp(14px,1.4vw,21px);margin:6px 0}.demoaction{position:absolute;bottom:8%;left:7%;right:7%;height:16%;background:url('Buttons/button-primary-normal.png') center/100% 100%;display:flex;align-items:center;justify-content:center;color:#101c29;font-family:DawnTitle;font-size:clamp(20px,2vw,32px)}.demonav{position:absolute;bottom:0;left:0;right:0;height:12%;display:flex;align-items:center;justify-content:space-around;background:#101c29f5;font-family:DawnTitle;font-size:clamp(17px,1.8vw,28px)}.demonav .selected{color:#d6af5b}details{border:1px solid #526571;padding:16px;margin:20px 0}summary{cursor:pointer;color:#d6af5b}
</style></head><body><header><img src="Brand/heroes-dawn-ivory.png" style="width:min(100%,540px)" alt="Heroes Dawn"><h1>Kit complet Aube tactique</h1><p>Assets séparés issus de la galerie approuvée : surfaces extensibles, contrôles et états, pictogrammes, cadres, illustrations et portraits. Les textes, prix et règles restent des données du jeu.</p>
'@
$intro=@'
<p><a href="__REFERENCE__">Ouvrir les 21 planches de référence</a> · <a href="manifest.json">Manifeste complet</a> · <a href="README.md">Guide Unity</a></p><p class="small">Assemblage de démonstration ci-dessous : il utilise les fichiers du kit et illustre leur composition. Ce rendu est une démonstration HTML du kit.</p></header>
'@
$intro=$intro.Replace('__REFERENCE__',$reference)
$body=@'
<main><section class="demo" aria-label="Assemblage des assets de boutique"><div class="demohead"><span>BOUTIQUE</span><span>CR 800 · PR 160 · GM 50</span></div><div class="demorail"><div class="demotab">HÉROS</div><div class="demotab selected">BOOSTERS</div><div class="demotab">RESSOURCES</div></div><div class="demooffers"><div class="offer"><img src="Illustrations/Generated/shop-pack-operation.png" alt="Paquet Opération"><span>Pack Opération</span></div><div class="offer"><img src="Illustrations/Generated/shop-pack-mission.png" alt="Paquet Mission"><span>Pack Mission</span></div></div><div class="demodetail"><h3>Pack Mission</h3><p>Contenu du paquet</p><p>Ressources et dossier</p><p class="small">Valeurs de démonstration ; contenu à relier aux données du jeu.</p><div class="demoaction">✦ ACHETER</div></div><div class="demonav"><span>QG</span><span>ÉQUIPE</span><span>PASS</span><span class="selected">BOUTIQUE</span><span>PROFIL</span></div></section><h2>Catalogue des fichiers</h2><p id="count"></p><div class="groups" id="groups"></div></main><div class="toolbar"><div><input id="search" type="search" placeholder="Chercher un asset, un état ou une famille…" aria-label="Rechercher"><button id="checker">Fond damier</button><button id="reset">Tout afficher</button></div></div><main><div class="grid" id="grid"></div></main><footer><p>Les PNG conservent leur alpha. Les cadres et boutons disposent de bordures 9-slice dans le manifeste et dans leurs réglages Unity. Les SVG sont éditables ; les portraits cadrés pointent vers les illustrations originales conservées.</p></footer>
<script>
'@
$script=@'
let group=''; const grid=document.getElementById('grid'), search=document.getElementById('search');
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n}
function render(){const q=search.value.toLocaleLowerCase('fr');const list=data.filter(a=>(!group||a.category===group)&&(!q||(a.id+' '+a.usage).toLocaleLowerCase('fr').includes(q)));grid.replaceChildren();document.getElementById('count').textContent=list.length+' fichiers affichés / '+data.length+' entrées du kit';for(const a of list){const card=el('article');card.className='card';const preview=el('div');preview.className='preview';if(a.preview){const im=el('img');im.loading='lazy';im.src=a.preview;im.alt=a.id;preview.append(im)}else{const t=el('span','Heroes Dawn — À l’aube');t.className='fontpreview';preview.append(t)}const meta=el('div');meta.className='meta';meta.append(el('h3',a.id));const dims=el('div',a.width?`${a.width} × ${a.height} · ${a.kind}`:a.kind);dims.className='dim';meta.append(dims,el('p',a.usage));if(a.border&&a.border.some(v=>v)){const b=el('p','9-slice G/B/D/H : '+a.border.join(' / '));b.className='dim';meta.append(b)}const links=el('div');links.className='links';for(const [label,url] of [['Fichier',a.file],['Source',a.source]]){if(!url)continue;const link=el('a',label);link.href=url;links.append(link)}meta.append(links);card.append(preview,meta);grid.append(card)}document.querySelectorAll('#groups button').forEach(b=>b.classList.toggle('active',b.dataset.group===group))}
for(const c of [...new Set(data.map(a=>a.category))]){const b=el('button',c);b.dataset.group=c;b.onclick=()=>{group=c;render()};document.getElementById('groups').append(b)}search.oninput=render;document.getElementById('reset').onclick=()=>{group='';search.value='';render()};document.getElementById('checker').onclick=()=>document.body.classList.toggle('checker');render();
</script></body></html>
'@
$html=$head+$intro+$body+'const data='+$recordJson+';'+$script
[IO.File]::WriteAllText((Join-Path $root 'catalogue.html'),$html)
$redirect=[IO.Path]::GetRelativePath($PSScriptRoot,(Join-Path $root 'catalogue.html')).Replace('\','/')
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'index.html'),('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url='+$redirect+'"><a href="'+$redirect+'">Ouvrir le catalogue du kit Aube tactique</a>'))
Write-Output "Catalogue créé : $($records.Count) entrées."
